// A vector member reached through a base class also triggers realignment
// on Linux/MinGW/Cygwin, matching real GCC (recursion in
// getX86VectorRegisterVarArgAlign() walks base classes, not just fields).
typedef float __v4sf __attribute__((__vector_size__(16)));
struct VecBase { __v4sf v; };
struct VecDerived : VecBase { int tag; };

// CHECK-LABEL: @_Z16base_vector_testiz(
